import 'package:flutter/material.dart';
import '../models/for_you_mix.dart';
import '../models/track_item.dart';
import '../l10n/translation_core.dart';
import 'playback_controller.dart';

/// Autogenerated mixes service for the "For You" page and Home section
class ForYouService {
  static final ForYouService instance = ForYouService._internal();
  ForYouService._internal();

  /// Generates dynamic mixes based on current library tracks or sample fallbacks
  List<ForYouMix> generateMixes(BuildContext context, List<TrackItem> libraryTracks) {
    final l10n = AppLocalizations.instance;

    // 1. Picks For You
    final quickPicksTracks = libraryTracks.isNotEmpty
        ? libraryTracks.take(8).toList()
        : _buildSampleTracks('Picks');

    // 2. Energy & Drive Mix (BPM > 125 or aggressive genres)
    final energyTracks = libraryTracks
        .where((t) => t.effectiveBpm >= 125 || t.genre == 'Rock' || t.genre == 'Electronic')
        .toList();
    final finalEnergyTracks = energyTracks.isNotEmpty
        ? energyTracks.take(8).toList()
        : (libraryTracks.isNotEmpty ? libraryTracks.take(6).toList() : _buildSampleTracks('Energy'));

    // 3. Chill & Mellow Vibes
    final chillTracks = libraryTracks
        .where((t) => t.effectiveBpm > 0 && t.effectiveBpm < 125 || t.genre == 'Acoustic' || t.genre == 'Pop' || t.genre == 'Jazz')
        .toList();
    final finalChillTracks = chillTracks.isNotEmpty
        ? chillTracks.take(8).toList()
        : (libraryTracks.isNotEmpty ? libraryTracks.reversed.take(6).toList() : _buildSampleTracks('Chill'));

    // 4. BPM Groove Station (Tempo clustered)
    final bpmTracks = libraryTracks.isNotEmpty
        ? (List<TrackItem>.from(libraryTracks)..sort((a, b) => a.effectiveBpm.compareTo(b.effectiveBpm))).take(8).toList()
        : _buildSampleTracks('BPM');

    // 5. Rediscover & Deep Cuts
    final rediscoverTracks = libraryTracks.isNotEmpty
        ? libraryTracks.skip(2).take(8).toList()
        : _buildSampleTracks('Rediscover');

    return [
      ForYouMix(
        id: 'mix_quick_picks',
        title: l10n.t('mix_quick_picks_title'),
        subtitle: l10n.t('mix_quick_picks_desc'),
        vibeCategory: 'picks',
        tracks: quickPicksTracks,
        primaryColor: const Color(0xFF6366F1), // Indigo
        secondaryColor: const Color(0xFFEC4899), // Pink
        artStyle: ForYouArtStyle.geometricPulse,
        badge: 'MIX 01',
      ),
      ForYouMix(
        id: 'mix_energy',
        title: l10n.t('mix_energy_title'),
        subtitle: l10n.t('mix_energy_desc'),
        vibeCategory: 'energy',
        tracks: finalEnergyTracks,
        primaryColor: const Color(0xFFF97316), // Orange
        secondaryColor: const Color(0xFFEF4444), // Crimson Red
        artStyle: ForYouArtStyle.starburst,
        badge: 'ENERGY',
      ),
      ForYouMix(
        id: 'mix_chill',
        title: l10n.t('mix_chill_title'),
        subtitle: l10n.t('mix_chill_desc'),
        vibeCategory: 'chill',
        tracks: finalChillTracks,
        primaryColor: const Color(0xFF06B6D4), // Cyan
        secondaryColor: const Color(0xFF3B82F6), // Blue
        artStyle: ForYouArtStyle.sonicWave,
        badge: 'MELLOW',
      ),
      ForYouMix(
        id: 'mix_bpm_sync',
        title: l10n.t('mix_bpm_sync_title'),
        subtitle: l10n.t('mix_bpm_sync_desc'),
        vibeCategory: 'groove',
        tracks: bpmTracks,
        primaryColor: const Color(0xFF8B5CF6), // Purple
        secondaryColor: const Color(0xFF10B981), // Emerald
        artStyle: ForYouArtStyle.radialDisc,
        badge: 'GROOVE',
      ),
      ForYouMix(
        id: 'mix_rediscover',
        title: l10n.t('mix_rediscover_title'),
        subtitle: l10n.t('mix_rediscover_desc'),
        vibeCategory: 'rediscover',
        tracks: rediscoverTracks,
        primaryColor: const Color(0xFF14B8A6), // Teal
        secondaryColor: const Color(0xFFF59E0B), // Amber
        artStyle: ForYouArtStyle.orbitBloom,
        badge: 'DEEP CUTS',
      ),
    ];
  }

  /// Plays an autogenerated mix immediately using Smart Shuffle
  void playMix(ForYouMix mix, {VoidCallback? onOpenNowPlaying}) {
    if (mix.tracks.isEmpty) return;
    final controller = PlaybackController.instance;

    controller.setShuffleMode(ShuffleMode.smart);
    controller.playTrack(mix.tracks.first);
    onOpenNowPlaying?.call();
  }

  List<TrackItem> _buildSampleTracks(String prefix) {
    return List.generate(
      4,
      (i) => TrackItem(
        id: 'sample_${prefix.toLowerCase()}_$i',
        title: '$prefix Vibe Anthem #$i',
        artist: 'Attune Algorithmic Mix',
        album: 'For You Auto-Mix',
        filePath: '',
        duration: Duration(minutes: 3, seconds: 15 + i * 20),
        bpm: 124.0 + i * 2.0,
        musicalKey: '${(i % 12) + 1}A',
        genre: prefix == 'Energy' ? 'Rock' : (prefix == 'Chill' ? 'Acoustic' : 'Pop'),
        format: 'FLAC',
      ),
    );
  }
}
